void Error_Handler(void);

/* USER CODE BEGIN 0 */
// VSS/VO/RW/K→GND, VDD→5V, A→220 Ω→5V · RS PB0, E PB1, DB4~7 PB4~7 · DB0~3 미연결
void lcdNibble(uint8_t value) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_4, (value & 1) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_5, (value & 2) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_6, (value & 4) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_7, (value & 8) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);
    HAL_Delay(1);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET);
    HAL_Delay(1);
}
void lcdSend(uint8_t value, uint8_t data) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, data ? GPIO_PIN_SET : GPIO_PIN_RESET);
    lcdNibble(value >> 4);
    lcdNibble(value & 15);
    HAL_Delay(2);
}
void lcdPrint(char text[]) {
    for (int i = 0; text[i] != 0; i++) lcdSend(text[i], 1);
}
/* USER CODE END 0 */

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART2_UART_Init();
    /* USER CODE BEGIN 2 */
    HAL_Delay(20);
    lcdNibble(3);
    HAL_Delay(5);
    lcdNibble(3);
    lcdNibble(3);
    lcdNibble(2);
    lcdSend(0x28, 0);
    lcdSend(0x0C, 0);
    lcdSend(0x06, 0);
    lcdSend(0x01, 0);
    char line1[] = "STM Emulator";
    char line2[] = "HAL 4-bit LCD";
    lcdPrint(line1);
    lcdSend(0xC0, 0);
    lcdPrint(line2);
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        HAL_Delay(100);
        /* USER CODE END 3 */
    }
}

void SystemClock_Config(void) {
    RCC_OscInitTypeDef osc = {0};
    RCC_ClkInitTypeDef clk = {0};
    __HAL_RCC_PWR_CLK_ENABLE();
    __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);
    osc.OscillatorType = RCC_OSCILLATORTYPE_HSI;
    osc.HSIState = RCC_HSI_ON;
    osc.HSICalibrationValue = RCC_HSICALIBRATION_DEFAULT;
    osc.PLL.PLLState = RCC_PLL_OFF;
