    MX_USART2_UART_Init();
    /* USER CODE BEGIN 2 */
    uint8_t commands[] = {0x00, 0xAE, 0x20, 0x02, 0xA8, 63, 0x8D, 0x14, 0xA4, 0xA6, 0xAF};
    printf("OLED init status=%d\n", HAL_I2C_Master_Transmit(&hi2c1, 0x3C << 1, commands, sizeof(commands), 100));
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        int status = HAL_OK;
        for (int page = 0; page < 8; page++) {
