            uint8_t pixels[129];
            pixels[0] = 0x40;
            for (int x = 0; x < 128; x++) pixels[x+1] = (x < oledFrame || x == 0 || x == 127) ? 255 : (page == 0 ? 1 : (page == 7 ? 128 : 0));
            status |= HAL_I2C_Master_Transmit(&hi2c1, 0x3C << 1, address, 4, 100);
            status |= HAL_I2C_Master_Transmit(&hi2c1, 0x3C << 1, pixels, 129, 100);
            HAL_Delay(1);
