uint8_t sensorCRC(uint8_t data[], int offset) {
    uint8_t crc = 255;
    for (int i = 0; i < 2; i++) {
        crc ^= data[offset+i];
        for (int bit = 0; bit < 8; bit++) crc = (crc & 128) ? (crc << 1) ^ 0x31 : crc << 1;
