    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_6, GPIO_PIN_RESET);
    sdByte(255);
    sdByte(0x40|command);
    sdByte(argument>>24);
    sdByte(argument>>16);
    sdByte(argument>>8);
    sdByte(argument);
    sdByte(crc);
    uint8_t result=255;
    for (uint32_t i=0;i<10;i++) {
        result=sdByte(255);
        if (!(result&128))break;
    }
    return result;
}
