    HAL_Delay(1);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET);
    HAL_Delay(1);
}
void lcdSend(uint8_t value, uint8_t data) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, data ? GPIO_PIN_SET : GPIO_PIN_RESET);
    lcdNibble(value >> 4);
    lcdNibble(value & 15);
    HAL_Delay(2);
}
